(function () {
  "use strict";

  function reduced() {
    return window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  }

  /* ------------------------------------------------------------------ rotator */
  function rotators() {
    document.querySelectorAll("[data-rotator]").forEach(function (el) {
      var words = (el.getAttribute("data-rotator") || "").split("|").filter(Boolean);
      if (words.length < 2) return;
      if (reduced()) { el.textContent = words[0]; return; }
      var i = 0;
      var node = document.createElement("span");
      node.className = "rotator__word";
      node.textContent = words[0];
      el.textContent = "";
      el.appendChild(node);
      setInterval(function () {
        i = (i + 1) % words.length;
        node.classList.add("is-out");
        setTimeout(function () {
          node.textContent = words[i];
          node.classList.remove("is-out");
        }, 300);
      }, 3000);
    });
  }

  /* ------------------------------------------------------------------ journey */
  function journeys() {
    document.querySelectorAll("[data-journey]").forEach(function (root) {
      var data;
      try { data = JSON.parse(root.getAttribute("data-journey")); }
      catch (e) { return; }
      var buttons = Array.prototype.slice.call(root.querySelectorAll("[data-opt]"));
      var num = root.querySelector("[data-journey-num]");
      var label = root.querySelector("[data-journey-label]");
      var title = root.querySelector("[data-journey-title]");
      var copy = root.querySelector("[data-journey-copy]");
      function render(idx) {
        buttons.forEach(function (b, k) {
          b.classList.toggle("is-active", k === idx);
          b.setAttribute("aria-pressed", k === idx ? "true" : "false");
        });
        var d = data[idx] || {};
        if (num) num.textContent = ("0" + (idx + 1)).slice(-2) + " / " + ("0" + buttons.length).slice(-2);
        if (label) label.textContent = d.label || "Recommended starting point";
        if (title) title.textContent = d.title || "";
        if (copy) copy.textContent = d.copy || "";
      }
      buttons.forEach(function (b, k) {
        b.addEventListener("click", function () { render(k); });
      });
      render(0);
    });
  }

  /* ------------------------------------------------------------------- slider */
  function sliders() {
    document.querySelectorAll("[data-slider]").forEach(function (root) {
      var track = root.querySelector(".slider__track");
      if (!track) return;
      var slides = Array.prototype.slice.call(track.children);
      var count = root.querySelector(".slide-count");
      var prev = root.querySelector("[data-slide-prev]");
      var next = root.querySelector("[data-slide-next]");
      var dots = Array.prototype.slice.call(root.querySelectorAll(".slider__progress span"));
      var i = 0;
      function go(idx) {
        i = Math.max(0, Math.min(slides.length - 1, idx));
        var el = slides[i];
        if (el && track.scrollTo) track.scrollTo({ left: el.offsetLeft, behavior: reduced() ? "auto" : "smooth" });
        if (count) count.textContent = ("0" + (i + 1)).slice(-2) + " / " + ("0" + slides.length).slice(-2);
        dots.forEach(function (d, k) { d.classList.toggle("is-active", k === i); });
      }
      if (prev) prev.addEventListener("click", function () { go(i - 1); });
      if (next) next.addEventListener("click", function () { go(i + 1); });
      go(0);
    });
  }

  /* --------------------------------------------------------------------- tabs */
  function tabs() {
    document.querySelectorAll("[data-tabs]").forEach(function (root) {
      var triggers = Array.prototype.slice.call(root.querySelectorAll('[role="tab"]'));
      var panels = Array.prototype.slice.call(root.querySelectorAll('[role="tabpanel"]'));
      function activate(idx) {
        triggers.forEach(function (t, k) {
          t.setAttribute("aria-selected", k === idx ? "true" : "false");
          t.tabIndex = k === idx ? 0 : -1;
        });
        panels.forEach(function (p, k) {
          if (k === idx) p.removeAttribute("hidden");
          else p.setAttribute("hidden", "");
        });
      }
      triggers.forEach(function (t, k) {
        t.addEventListener("click", function () { activate(k); });
        t.addEventListener("keydown", function (e) {
          if (e.key === "ArrowRight") { activate((k + 1) % triggers.length); triggers[(k + 1) % triggers.length].focus(); }
          if (e.key === "ArrowLeft") { activate((k - 1 + triggers.length) % triggers.length); triggers[(k - 1 + triggers.length) % triggers.length].focus(); }
        });
      });
      activate(0);
    });
  }

  /* ------------------------------------------------------------------- panels */
  function panels() {
    document.querySelectorAll("[data-panels]").forEach(function (root) {
      var items = Array.prototype.slice.call(root.querySelectorAll(".panel"));
      items.forEach(function (panel) {
        var btn = panel.querySelector(".panel__btn");
        if (!btn) return;
        btn.addEventListener("click", function () {
          var open = panel.classList.contains("is-open");
          items.forEach(function (p) { p.classList.remove("is-open"); p.querySelector(".panel__btn").setAttribute("aria-expanded", "false"); });
          if (!open) { panel.classList.add("is-open"); btn.setAttribute("aria-expanded", "true"); }
        });
      });
      var first = items[0];
      if (first) { first.classList.add("is-open"); first.querySelector(".panel__btn").setAttribute("aria-expanded", "true"); }
    });
  }

  /* -------------------------------------------------------------------- draw */
  function draw() {
    document.querySelectorAll("[data-draw]").forEach(function (p) {
      p.style.strokeDasharray = "100";
      p.style.strokeDashoffset = "100";
      if (!("IntersectionObserver" in window) || reduced()) { p.style.strokeDashoffset = "0"; return; }
      var io = new IntersectionObserver(function (es) {
        es.forEach(function (e) {
          if (e.isIntersecting) { p.style.strokeDashoffset = "0"; io.disconnect(); }
        });
      }, { rootMargin: "0px 0px -15% 0px" });
      io.observe(p);
    });
  }

  function init() {
    rotators();
    journeys();
    sliders();
    tabs();
    panels();
    draw();
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();

/* ui-polish.js — focus management for the search overlay (bundled).
   The overlay fades in, so the field cannot take focus immediately: poll until
   it is actually visible, then focus. Escape returns focus to the trigger. */
(function () {
  "use strict";
  if (window.__qUiPolish) return;
  window.__qUiPolish = true;

  function field() { return document.querySelector(".qsearch__input"); }
  function visible(el) {
    if (!el) return false;
    var cs = getComputedStyle(el);
    return cs.visibility !== "hidden" && cs.display !== "none" && parseFloat(cs.opacity || "1") > 0.2;
  }
  function focusField(tries) {
    var f = field();
    if (f && visible(f)) {
      f.focus();
      if (document.activeElement === f) return;
    }
    if (tries > 0) setTimeout(function () { focusField(tries - 1); }, 90);
  }
  document.addEventListener("click", function (e) {
    if (!e.target.closest || !e.target.closest(".hdr__search")) return;
    setTimeout(function () { focusField(10); }, 60);
  }, true);
  document.addEventListener("keydown", function (e) {
    if (e.key !== "Escape") return;
    var open = document.querySelector(".qsearch");
    if (!open || getComputedStyle(open).visibility === "hidden") return;
    var t = document.querySelector(".hdr__search");
    if (t) t.focus();
  });
})();

/* =============================================================================
   planner-upgrade.js — presets, burn bar and sticky summary for the two
   credit calculators (homepage #calculator and the .pc widget on solutions).
   -----------------------------------------------------------------------------
   Runs after the calculators render, adds only presentation, and never changes
   the credit maths: presets set the quantity inputs, the existing calculator
   recomputes. Everything is skipped when the controls are absent.
   ========================================================================== */
(function () {
  "use strict";
  if (window.__qPlannerUpgrade) return;
  window.__qPlannerUpgrade = true;

  var PRESETS = [
    { key: "content", label: "Content month", q: { "q-posts": 16, "q-videos": 2, "q-visuals": 2, "q-assets": 8, "q-decks": 1 } },
    { key: "launch",  label: "Launch month",  q: { "q-posts": 6,  "q-videos": 3, "q-visuals": 4, "q-assets": 10, "q-decks": 2 } },
    { key: "steady",  label: "Steady state",  q: { "q-posts": 12, "q-videos": 4, "q-visuals": 1, "q-assets": 6,  "q-decks": 2 } }
  ];

  function setVal(el, v) {
    el.value = v;
    el.dispatchEvent(new Event("input", { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
  }

  /* ---------------------------------------------------------------- homepage */
  function upgradePlanner() {
    var posts = document.getElementById("q-posts");
    if (!posts || document.querySelector(".planner-presets")) return;

    var row = document.createElement("div");
    row.className = "planner-presets";
    row.setAttribute("role", "group");
    row.setAttribute("aria-label", "Example months");
    row.innerHTML = '<span class="planner-presets__label">Example months</span>';

    PRESETS.forEach(function (p) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = "planner-chip";
      b.textContent = p.label;
      b.addEventListener("click", function () {
        Object.keys(p.q).forEach(function (id) {
          var el = document.getElementById(id);
          if (el) setVal(el, p.q[id]);
        });
        row.querySelectorAll(".planner-chip").forEach(function (c) { c.classList.remove("is-on"); });
        b.classList.add("is-on");
        setTimeout(paintBar, 60);
      });
      row.appendChild(b);
    });

    posts.closest(".stack, .calc-form, form, div").parentNode.insertBefore(row, posts.closest(".stack, .calc-form, form, div"));

    // burn bar in front of the metric row
    var anchor = document.getElementById("stat-used");
    if (anchor && !document.querySelector(".burnbar")) {
      var bar = document.createElement("div");
      bar.className = "burnbar";
      bar.setAttribute("aria-hidden", "true");
      bar.innerHTML = '<i></i>';
      var host = anchor.closest(".calc-metrics, .between, .row, div") || anchor.parentNode;
      host.parentNode.insertBefore(bar, host);
    }
    paintBar();
  }

  function paintBar() {
    var bar = document.querySelector(".burnbar > i");
    var pctEl = document.getElementById("stat-pct");
    if (!bar || !pctEl) return;
    var pct = parseFloat((pctEl.textContent || "0").replace("%", "")) || 0;
    bar.style.width = Math.max(0, Math.min(100, pct)) + "%";
    bar.classList.toggle("is-over", pct > 100);
  }

  document.addEventListener("input", function (e) {
    if (e.target && /^q-/.test(e.target.id || "")) paintBar();
  }, true);

  /* --------------------------------------------------------------- solutions */
  function upgradePc() {
    var host = document.querySelector("[data-pod-calculator] .pc");
    if (!host || host.querySelector(".pc__bar")) return;
    var rng = host.querySelector('input[type="range"]');
    var out = host.querySelector(".pc__out");
    if (!rng || !out) return;

    var bar = document.createElement("div");
    bar.className = "pc__bar";
    bar.setAttribute("aria-hidden", "true");
    bar.innerHTML = '<i></i>';
    rng.parentNode.insertBefore(bar, rng.nextSibling);

    function paint() {
      var max = parseFloat(rng.max) || 120;
      var val = parseFloat(rng.value) || 0;
      var fill = bar.querySelector("i");
      fill.style.width = Math.max(0, Math.min(100, (val / max) * 100)) + "%";
      fill.classList.toggle("is-over", val > max);
    }
    rng.addEventListener("input", paint);
    rng.addEventListener("change", paint);
    paint();
  }

  function run() {
    upgradePlanner();
    upgradePc();
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", run);
  else run();
  // calculators render on their own schedule; retry briefly
  var tries = 0;
  var t = setInterval(function () {
    run();
    if (++tries > 12) clearInterval(t);
  }, 350);
})();

/* a11y-current.js — mark the section link for the page you are on. */
(function () {
  "use strict";
  var parts = location.pathname.split("/").filter(Boolean);
  var page = parts.pop() || "index.html";
  var root = parts.length ? parts[parts.length - 1] + ".html" : page;
  document.querySelectorAll(".nav a[href], .drawer a[href], .mnav a[href]").forEach(function (a) {
    var base = a.getAttribute("href").split("#")[0].split("?")[0].split("/").pop();
    if (base === page || base === root) a.setAttribute("aria-current", "page");
  });
})();
